class Money:
    def __init__(self, cents):
        self.cents = cents

    def __add__(self, o):
        return Money(self.cents + o.cents)

    def __eq__(self, o):
        return isinstance(o, Money) and self.cents == o.cents

    def __repr__(self):
        return f'Money({self.cents})'

    def __str__(self):
        sign = '-' if self.cents < 0 else ''
        return f'{sign}${abs(self.cents) / 100:,.2f}'

    def split(self, n):
        sign = -1 if self.cents < 0 else 1
        q, r = divmod(abs(self.cents), n)
        shares = [q + 1] * r + [q] * (n - r)
        return [Money(sign * s) for s in shares]
